import {fixtureControls} from './tyre-fixture-ui.js';
import {validate,inputFromRecord,MODEL,MEASURED_MODEL} from './tyre-fixture.js';
const $=id=>document.getElementById(id);
let examples=[],input=null,accepted=null,worker=null,revision=0;
function stop(){revision++;worker?.terminate();worker=null;$('cancel').disabled=true;$('experiment').setAttribute('aria-busy','false');}
function invalidate(message){stop();accepted=null;$('status').textContent=message;$('save').disabled=true;$('scrub').disabled=true;$('progress').hidden=true;for(const id of ['progressText','result','ledger','intervalSummary','error'])$(id).textContent='';for(const id of ['time','force','speed'])$(id).textContent='—';for(const id of ['rig','history']){const c=$(id);c.getContext('2d').clearRect(0,0,c.width,c.height);}}
function useInput(value){input=validate(value);$('setupText').value=JSON.stringify(input,null,2);for(const id of ['rates','dt','duration']){const value=id==='rates'?input.rates:input.motion[id],select=$(id);if(!Array.from(select.options).some(o=>o.value===String(value)))select.add(new Option(String(value),String(value)));select.value=String(value);}$('measure').checked=!!input.measurement;$('measure').disabled=input.motion.duration>.1;const s=input.seed.source;$('source').textContent=s.bike+' · '+s.wheel+' · source '+s.time.toFixed(5)+' s · '+(input.rates==='zero'?'zero node velocities':'imported node velocities')+' · fixed hub';}
function launch(payload,ticket=revision){
 if(ticket!==revision)return;$('status').textContent='CALCULATING';$('experiment').setAttribute('aria-busy','true');$('cancel').disabled=false;$('progress').hidden=false;$('progress').removeAttribute('value');
 const fail=message=>{if(ticket!==revision)return;invalidate('CALCULATION FAILED');$('error').textContent=message;};
 try{worker=new Worker(new URL('./tyre-fixture-worker.js',import.meta.url),{type:'module'});worker.onerror=e=>{e.preventDefault();fail(e.message||'Worker failed.');};worker.onmessage=e=>{
  if(ticket!==revision)return;if(e.data.error){fail(e.data.error);return;}
  try{if(e.data.progress){const p=e.data.progress;if(!['extracting','preparing','initializing','integrating','finalizing'].includes(p.phase)||!Number.isSafeInteger(p.acceptedSteps)||!Number.isSafeInteger(p.totalSteps)||p.totalSteps<1||p.acceptedSteps<0||p.acceptedSteps>p.totalSteps||!Number.isFinite(p.dt)||p.dt<0)throw Error('Invalid fixture progress.');if(['extracting','preparing','initializing'].includes(p.phase))$('progress').removeAttribute('value');else $('progress').value=p.acceptedSteps/p.totalSteps;$('progressText').textContent=p.phase+' · '+p.acceptedSteps+' / '+p.totalSteps+' accepted steps · '+(p.acceptedSteps*p.dt).toFixed(5)+' s';return;}
   stop();accepted=e.data.result;useInput(accepted.scenario);for(const o of $('channel').options)if(o.value.startsWith('interval-'))o.disabled=!accepted.observation?.intervals.length;$('historyScope').value='all';$('historyScope').options[1].disabled=!(accepted.observation?.windowFrameIndices.length>1);if(accepted.observation?.intervals.length)$('channel').value='interval-rms';else if($('channel').value.startsWith('interval-'))$('channel').value='node';$('status').textContent=accepted.status.toUpperCase();$('save').disabled=false;$('scrub').disabled=!accepted.frames.length;$('scrub').max=Math.max(0,accepted.frames.length-1);$('scrub').value=0;$('progress').value=accepted.summary.steps/Math.round(input.motion.duration/input.motion.dt);$('progressText').textContent=accepted.summary.steps+' accepted steps · '+accepted.summary.acceptedTime.toFixed(5)+' s';$('result').textContent=accepted.termination?'Stopped: '+accepted.termination.reason+' · no unsupported continuation':'Completed control · not an equilibrium or stable-idle result';draw();
  }catch(error){invalidate('CALCULATION FAILED');$('error').textContent=error.message;}
 };worker.postMessage(payload);}catch(error){fail(error.message);}
}
function calculate(){invalidate('PREPARING');try{
 if(!input)throw Error('No fixture seed loaded.');const a=fixtureControls(input,{rates:$('rates').value,dt:Number($('dt').value),duration:Number($('duration').value),measure:$('measure').checked});
 useInput(a);launch({input});
}catch(e){$('status').textContent='INPUT REJECTED';$('error').textContent=e.message;}}

function canvas(id){const c=$(id),rect=c.getBoundingClientRect(),width=rect.width,height=rect.height,dpr=devicePixelRatio||1;c.width=Math.max(1,Math.round(width*dpr));c.height=height*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);return {ctx,width,height};}
function draw(){
 if(!accepted?.frames.length)return;const f=accepted.frames[Number($('scrub').value)],s=accepted.scenario.seed,w=s.wheel,hub=[s.hub.position[0],s.hub.position[2]];
 const {ctx,width,height}=canvas('rig'),scale=Math.min((width-35)/.85,285/.85),X=x=>width/2+(x-hub[0])*scale,Z=z=>height/2-(z-hub[1])*scale;
 ctx.strokeStyle='#657984';ctx.beginPath();ctx.moveTo(0,Z(s.profile.points[0][1]));ctx.lineTo(width,Z(s.profile.points[0][1]));ctx.stroke();
 ctx.strokeStyle='#a997f4';ctx.lineWidth=2;ctx.beginPath();ctx.arc(X(hub[0]),Z(hub[1]),w.rimRadius*scale,0,2*Math.PI);ctx.stroke();ctx.strokeRect(X(hub[0])-7,Z(hub[1])-7,14,14);
 ctx.strokeStyle='#70e2ce';ctx.beginPath();f.nodes.forEach((p,i)=>i?ctx.lineTo(X(p[0]),Z(p[1])):ctx.moveTo(X(p[0]),Z(p[1])));ctx.closePath();ctx.stroke();
 ctx.fillStyle='#70e2ce';ctx.beginPath();ctx.arc(X(f.nodes[0][0]),Z(f.nodes[0][1]),3,0,2*Math.PI);ctx.fill();
 ctx.strokeStyle='#f2b373';for(const c of f.contacts){const x=X(c.point[0]),y=Z(c.point[1]),dx=c.force[0]*scale*.002,dy=-c.force[1]*scale*.002;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+dx,y+dy);const angle=Math.atan2(dy,dx);ctx.moveTo(x+dx-5*Math.cos(angle-.5),y+dy-5*Math.sin(angle-.5));ctx.lineTo(x+dx,y+dy);ctx.lineTo(x+dx-5*Math.cos(angle+.5),y+dy-5*Math.sin(angle+.5));ctx.stroke();}
 ctx.fillStyle='#9aabb7';ctx.font='12px system-ui';ctx.fillText('x →  z ↑ · equal scale',12,20);
 $('time').textContent=f.time.toFixed(5)+' s';$('force').textContent=f.ground[1].toFixed(2)+' N';$('speed').textContent=f.tyreMotion.rmsSpeed.toExponential(3)+' m/s';
 $('ledger').textContent='Energy residual '+f.residual.toExponential(3)+' J · damping loss '+f.dampingLoss.toExponential(3)+' J · signed contact work '+f.contactWork.toExponential(3)+' J · clamp work 0 J. Clamp inferred from balance [Fx, Fz, My]: '+f.clamp.map(x=>x.toFixed(3)).join(', ')+' [N, N, N m]. Nodal/contact moment difference '+f.contactMomentDifference.toExponential(3)+' N m; not a measured bearing torque.';
 const intervals=accepted.observation?.intervals??[],bin=intervals.find(b=>f.time<=b.endTime+1e-9);
 $('intervalSummary').textContent=bin?'Every accepted physics step · '+bin.startTime.toFixed(3)+'–'+bin.endTime.toFixed(3)+' s'+(bin.complete?'':' (partial)')+' · RMS '+bin.timeRmsNodeSpeed.toExponential(3)+' m/s · peak '+bin.maxEndpointNodeSpeed.value.toExponential(3)+' m/s · peak acceleration '+bin.maxEndpointNodeAcceleration.value.toExponential(3)+' m/s² · load deviation '+bin.timeStdVerticalForce.toExponential(3)+' N · residual increment '+bin.residualIncrement.toExponential(3)+' J. Discrete endpoint measurements; no settling certification.':'';
 const graph=canvas('history'),g=graph.ctx,key=$('channel').value,visibleFrames=$('historyScope').value==='window'?(accepted.observation?.windowFrameIndices??[]).map(i=>accepted.frames[i]):accepted.frames;
 const points=key.startsWith('interval-')?intervals.flatMap(b=>{const value=key==='interval-rms'?b.timeRmsNodeSpeed:key==='interval-force'?b.timeStdVerticalForce:b.maxEndpointNodeAcceleration.value;return [{time:b.startTime,value},{time:b.endTime,value}];}):visibleFrames.map(f=>({time:f.time,value:key==='node'?f.tyreMotion.node0Velocity[1]:key==='rms'?f.tyreMotion.rmsSpeed:key==='force'?f.ground[1]:f.residual}));
 if(!points.length)return;const values=points.map(p=>p.value),lo=Math.min(...values),hi=Math.max(...values),span=Math.max(hi-lo,1e-10),start=visibleFrames[0]?.time??0,duration=Math.max((visibleFrames.at(-1)?.time??0)-start,1e-10),x=t=>45+(t-start)/duration*(graph.width-55),y=v=>155-(v-lo)/span*125;
 g.fillStyle='#9aabb7';g.font='11px system-ui';g.fillText(hi.toExponential(2),2,18);g.fillText(lo.toExponential(2),2,164);g.fillText(start.toFixed(3)+' s',45,185);g.fillText((start+duration).toFixed(3)+' s',Math.max(60,graph.width-55),185);g.strokeStyle='#70e2ce';g.beginPath();points.forEach((p,i)=>i?g.lineTo(x(p.time),y(p.value)):g.moveTo(x(p.time),y(p.value)));g.stroke();g.strokeStyle='#a997f4';g.beginPath();g.moveTo(x(f.time),25);g.lineTo(x(f.time),160);g.stroke();

}
$('calculate').onclick=calculate;$('cancel').onclick=()=>invalidate('CANCELLED');
for(const id of ['rates','dt','duration','measure'])$(id).onchange=()=>{invalidate('UNAPPLIED EDITS');const long=Number($('duration').value)>.1;$('measure').disabled=long;if(long)$('measure').checked=true;};
$('example').onchange=()=>{invalidate('UNAPPLIED EDITS');const entry=examples.find(x=>x.name===$('example').value);if(entry)useInput(entry.input);else{input=null;$('status').textContent='INPUT REJECTED';$('error').textContent='Examples are unavailable. Reload the page or load a saved input.';}};
$('setupText').oninput=()=>invalidate('UNAPPLIED EDITS');
$('applyJson').onclick=()=>{invalidate('PREPARING');try{useInput(JSON.parse($('setupText').value));$('example').value='custom';launch({input});}catch(e){$('status').textContent='INPUT REJECTED';$('error').textContent=e.message;}};
$('load').onchange=async()=>{const file=$('load').files[0];if(!file)return;$('load').value='';const selectedWheel=$('sourceWheel').value;invalidate('READING FILE');const ticket=revision;$('cancel').disabled=false;$('experiment').setAttribute('aria-busy','true');try{const value=JSON.parse(await file.text());if(ticket!==revision)return;$('example').value='custom';if([MODEL,MEASURED_MODEL].includes(value.model)){useInput(inputFromRecord(value));launch({input},ticket);}else if(value.model){launch({window:value,wheel:selectedWheel},ticket);}else{useInput(value);launch({input},ticket);}}catch(e){if(ticket===revision){invalidate('INPUT REJECTED');$('error').textContent=e.message;}}};
$('scrub').oninput=draw;$('channel').onchange=()=>{if($('channel').value.startsWith('interval-'))$('historyScope').value='all';draw();};$('historyScope').onchange=()=>{if($('historyScope').value==='window'&&$('channel').value.startsWith('interval-'))$('channel').value='node';draw();};new ResizeObserver(draw).observe($('rig'));
$('save').onclick=()=>{if(!accepted)return;const url=URL.createObjectURL(new Blob([JSON.stringify(accepted,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='bikelab-fixed-hub-casing.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
window.addEventListener('pagehide',()=>stop());
const startupTicket=revision;
try{const response=await fetch(new URL('./tyre-fixture-examples.json',import.meta.url));if(!response.ok)throw Error('Unable to load fixture examples.');const bundle=await response.json();if(bundle.format!=='bikelab-fixed-hub-examples-0.1'||!Array.isArray(bundle.cases)||!bundle.cases.length)throw Error('Invalid fixture examples.');examples=bundle.cases.map(e=>({...e,input:validate(e.input)}));if(startupTicket===revision){useInput(examples[0].input);calculate();}}catch(e){if(startupTicket===revision){invalidate('INPUT REJECTED');$('error').textContent=e.message;}}
